export function parseTerminationReason(value?:string|null){const match=(value||'').match(/^\[eSocial:(\d{2})\]\s*(.*)$/s);return {code:match?.[1]||'',reason:match?match[2]:(value||'')};}
export function terminationReasonValue(code:string,reason?:string|null){return [code?`[eSocial:${code}]`:'',reason?.trim()||''].filter(Boolean).join(' ')||null;}
export function terminationCodeLabel(code:string){const item=terminationCodes.find(option=>option.code===code);return item?`${item.code} · ${item.label}`:'';}
function terminationSummary(value?:string|null){const {code,reason}=parseTerminationReason(value);return [terminationCodeLabel(code),reason].filter(Boolean).join(' · ')||'—';}
