function changeDetails(change:Change){const before=change.before_state,after=change.after_state;if(!before||!after)return change.change_type==='admission'?'Entrada na equipe registrada.':'';const fields:[string,string][]=[['job_title','Cargo'],['seniority','Senioridade'],['department','Departamento'],['team_area','Setor'],['manager_code','Gestor'],['employment_type','Vínculo'],['weekly_hours','Jornada semanal'],['status','Situação']];return fields.filter(([key])=>String(before[key]??'')!==String(after[key]??'')).map(([key,label])=>`${label}: ${String(before[key]??'—')} → ${String(after[key]??'—')}`).join(' · ')||'Atualização dos dados da ficha, sem mudança de cargo ou área.';}
function currentMonth(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).formatToParts(new Date());return `${parts.find(part=>part.type==='year')?.value}-${parts.find(part=>part.type==='month')?.value}`;}
function monthLabel(month:string){const [y,m]=month.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(y,m-1,1));}
function dateLabel(s?:string|null){if(!s)return'—';return s.includes('T')?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo'}).format(new Date(s)):new Intl.DateTimeFormat('pt-BR').format(new Date(`${s.slice(0,10)}T12:00:00`));}
